mapper.sql:
WHERE m.factory_code IN #{code}
AND (m.factory_code LIKE CONCAT('%',#{keyword},'%') OR m.warehouse_code LIKE CONCAT('%',#{keyword},'%') OR m.warehouse_name LIKE CONCAT('%',#{keyword},'%'))
AND m.quality_configured=1 AND m.is_good_warehouse=1 AND m.quality_configured=1 AND m.is_good_warehouse=0 AND m.quality_configured=0

mapper.select:
SELECT COUNT(*) FROM factory_warehouse_mapping
WHERE factory_code=#{factoryCode} AND priority_no=#{priorityNo} AND enabled=1 AND is_good_warehouse=1
AND id <> #{excludeId}

mapper.update:
UPDATE stock_policy
SET safety_stock_qty=#{safetyStockQty}, warning_stock_qty=#{warningStockQty}, updated_by=#{updatedBy}, updated_at=NOW(3)
WHERE id=#{id}

UPDATE material_policy
SET supply_mode=#{supplyMode}, explosion_policy=#{explosionPolicy}, updated_by=#{updatedBy}, updated_at=NOW(3)
WHERE id=#{id}

mapper.select:
SELECT id, factory_code, calendar_date, is_production_day AS production_day,
       allocation_weight, daily_capacity, capacity_unit, revision, reason, created_by, created_at, updated_by, updated_at
FROM mrp_production_calendar WHERE id=#{id}

SELECT id, factory_code, calendar_date, is_production_day AS production_day,
       allocation_weight, daily_capacity, capacity_unit, revision, reason, created_by, created_at, updated_by, updated_at
FROM mrp_production_calendar WHERE factory_code=#{factoryCode} AND calendar_date=#{calendarDate}

mapper.insert:
INSERT INTO business_week_detail (version_id, week_code, start_date, end_date, sort_no)
SELECT #{versionId}, week_code, start_date, end_date, sort_no
FROM business_week WHERE business_month=#{businessMonth}
